"w:el protector solar":[["Póngase [protector solar]; el sol quema.", "Tragen Sie [Sonnencreme] auf; die Sonne brennt."], ["Se me acabó el [protector solar].", "Meine [Sonnencreme] ist leer."]],
"w:el repelente":[["Sin [repelente] no vamos a la selva.", "Ohne [Mückenschutz] gehen wir nicht in den Dschungel."], ["¿Tiene [repelente] natural?", "Haben Sie natürlichen [Mückenschutz]?"]],
"w:la marea":[["Con la [marea baja] se puede caminar a la isla.", "Bei [Ebbe] kann man zur Insel laufen."], ["La [marea] sube por la tarde.", "Am Nachmittag kommt die [Flut]."]],
"w:el mono":[["Un [mono] se robó mi sándwich.", "Ein [Affe] hat mein Sandwich geklaut."], ["Los [monos] aulladores nos despertaron.", "Die Brüll[affen] haben uns geweckt."]],
"w:el perezoso":[["Hay un [perezoso] en ese árbol.", "In dem Baum ist ein [Faultier]."], ["El [perezoso] se mueve muy despacio.", "Das [Faultier] bewegt sich sehr langsam."]],
"w:el tucán":[["Vimos un [tucán] en el jardín.", "Wir haben einen [Tukan] im Garten gesehen."], ["El [tucán] tiene un pico enorme.", "Der [Tukan] hat einen riesigen Schnabel."]],
"w:la rana":[["La [rana] de ojos rojos es famosa.", "Der Rotaugenlaub[frosch] ist berühmt."], ["De noche cantan las [ranas].", "Nachts quaken die [Frösche]."]],
"w:la tortuga":[["Vimos [tortugas] en Tortuguero.", "Wir haben in Tortuguero [Schildkröten] gesehen."], ["La [tortuga] pone sus huevos en la arena.", "Die [Schildkröte] legt ihre Eier in den Sand."]],
"w:el cocodrilo":[["Debajo del puente hay [cocodrilos].", "Unter der Brücke gibt es [Krokodile]."], ["¡Cuidado, un [cocodrilo] en el río!", "Vorsicht, ein [Krokodil] im Fluss!"]],
"w:la mariposa":[["La [mariposa] morfo es azul.", "Der Morpho-[Falter] ist blau."], ["Visitamos un jardín de [mariposas].", "Wir besuchen einen [Schmetterlings]garten."]],
"w:el pájaro":[["Hay muchos [pájaros] en la mañana.", "Morgens gibt es viele [Vögel]."], ["Ese [pájaro] es un quetzal.", "Dieser [Vogel] ist ein Quetzal."]],
"w:el mosquito":[["Hay muchos [mosquitos] en la noche.", "Nachts gibt es viele [Mücken]."], ["Me picó un [mosquito].", "Mich hat eine [Mücke] gestochen."]],
"w:la serpiente":[["Hay una [serpiente] en el sendero.", "Auf dem Weg ist eine [Schlange]."], ["¿Esa [serpiente] es venenosa?", "Ist diese [Schlange] giftig?"]],
