"w:la cabeza":[["Me duele la [cabeza].", "Mir tut der [Kopf] weh."], ["Póngase algo en la [cabeza]; el sol es fuerte.", "Setzen Sie etwas auf den [Kopf]; die Sonne ist stark."]],
"w:el ojo":[["Me entró arena en el [ojo].", "Ich habe Sand ins [Auge] bekommen."], ["Tengo el [ojo] rojo.", "Mein [Auge] ist rot."]],
"w:la nariz":[["Me sangra la [nariz].", "Meine [Nase] blutet."], ["Tengo la [nariz] tapada.", "Meine [Nase] ist verstopft."]],
