"w:el diente":[["Me duele un [diente].", "Mir tut ein [Zahn] weh."], ["Se me quebró un [diente].", "Mir ist ein [Zahn] abgebrochen."]],
"w:la oreja":[["Tengo agua en la [oreja].", "Ich habe Wasser im [Ohr]."], ["Me duele la [oreja] derecha.", "Mir tut das rechte [Ohr] weh."]],
