"w:la garganta":[["Me duele la [garganta].", "Mir tut der [Hals] weh."], ["Tengo la [garganta] irritada por el aire acondicionado.", "Mein [Rachen] ist von der Klimaanlage gereizt."]],
"w:el hombro":[["Me quemé los [hombros] en la playa.", "Ich habe mir am Strand die [Schultern] verbrannt."], ["Me duele el [hombro] después del rafting.", "Nach dem Rafting tut mir die [Schulter] weh."]],
"w:el brazo":[["Me picó algo en el [brazo].", "Mich hat etwas in den [Arm] gestochen."], ["Tengo el [brazo] hinchado.", "Mein [Arm] ist geschwollen."]],
"w:la mano":[["Me corté la [mano] con un coco.", "Ich habe mir an einer Kokosnuss die [Hand] geschnitten."], ["Lávese las [manos] antes de comer.", "Waschen Sie sich vor dem Essen die [Hände]."]],
"w:el dedo":[["Me lastimé el [dedo].", "Ich habe mir den [Finger] verletzt."], ["El anillo no me pasa por el [dedo].", "Der Ring geht mir nicht über den [Finger]."]],
"w:la espalda":[["Me duele la [espalda] después del bus.", "Nach der Busfahrt tut mir der [Rücken] weh."], ["Póngame protector en la [espalda], por favor.", "Creme mir bitte den [Rücken] ein."]],
"w:el estómago":[["Me duele el [estómago].", "Mir tut der [Bauch] weh."], ["Tengo el [estómago] delicado.", "Ich habe einen empfindlichen [Magen]."]],
"w:la pierna":[["Me duelen las [piernas] después de la caminata.", "Nach der Wanderung tun mir die [Beine] weh."], ["Tengo muchas picaduras en las [piernas].", "Ich habe viele Stiche an den [Beinen]."]],
"w:la rodilla":[["Me golpeé la [rodilla].", "Ich habe mir das [Knie] gestoßen."], ["Me duele la [rodilla] al bajar.", "Beim Abstieg tut mir das [Knie] weh."]],
"w:el pie":[["Me torcí el [pie] en el sendero.", "Ich habe mir auf dem Weg den [Fuß] verstaucht."], ["Vamos a [pie] hasta la playa.", "Wir gehen zu [Fuß] zum Strand."]],
"w:la piel":[["Tengo la [piel] muy roja.", "Meine [Haut] ist sehr rot."], ["Tengo la [piel] sensible.", "Ich habe empfindliche [Haut]."]],
"w:el corazón":[["El [corazón] me late muy rápido.", "Mein [Herz] schlägt sehr schnell."], ["Costa Rica se quedó en nuestro [corazón].", "Costa Rica bleibt in unserem [Herzen]."]],
"w:el dolor":[["Tengo [dolor] de cabeza.", "Ich habe Kopf[schmerzen]."], ["¿Tiene algo para el [dolor]?", "Haben Sie etwas gegen die [Schmerzen]?"]],
