"w:el novio / la novia":[["Los [novios] llegaron en carreta.", "Das Braut[paar] kam mit dem Ochsenkarren."], ["La [novia] llevaba flores del campo.", "Die [Braut] trug Wiesenblumen."]],
"w:el niño / la niña":[["Los [niños] juegan en la playa.", "Die [Kinder] spielen am Strand."], ["La [niña] vende pipas en la calle.", "Das [Mädchen] verkauft Trinkkokosnüsse auf der Straße."]],
"w:el hombre":[["El [hombre] del kiosco habla alemán.", "Der [Mann] am Kiosk spricht Deutsch."], ["Ese [hombre] es nuestro guía.", "Dieser [Mann] ist unser Guide."]],
"w:la mujer":[["La [mujer] de la recepción es muy amable.", "Die [Frau] an der Rezeption ist sehr nett."], ["Una [mujer] nos ayudó con el mapa.", "Eine [Frau] hat uns mit der Karte geholfen."]],
"w:el señor / la señora":[["Buenos días, [señora].", "Guten Morgen, [die Dame]."], ["El [señor] de la soda cocina muy rico.", "Der [Herr] von der Soda kocht sehr gut."]],
